//! SSX 3 (USA) — native recompilation, windowed front end.
//!
//! Boots the recompiled EE code (`ssx3-ee`, generated by `recomp-ee`) on the
//! `ssx3-ps2` platform layer and presents GS output with `wgpu`.
//!
//! Keys (pad 1): arrows = d-pad, X = Cross, Z = Square, S = Circle, A = Triangle,
//! Enter = Start, Right Shift = Select, Q/W = L1/R1, 1/2 = L2/R2.
//! Game controllers (via gilrs) map to pad 1 too, analog sticks included.

use std::sync::Arc;
use std::time::{Duration, Instant};

use winit::application::ApplicationHandler;
use winit::event::{ElementState, WindowEvent};
use winit::event_loop::{ActiveEventLoop, ControlFlow, EventLoop};
use winit::keyboard::{KeyCode, PhysicalKey};
use winit::window::{Window, WindowId};

mod game;
mod png;
mod present;

use present::Presenter;
use ssx3_ps2::Cpu;

struct App {
    cpu: Box<Cpu>,
    window: Option<Arc<Window>>,
    presenter: Option<Presenter>,
    frame: Vec<u32>,
    last: Instant,
    started: Instant,
    exit_after: Option<u64>,
    shots: u64,
    fps_mark: Instant,
    /// Pad 1 buttons held on the keyboard / on a game controller (libpad bits).
    keys: u16,
    gilrs: Option<gilrs::Gilrs>,
    /// Ticket of the previous frame's display request (MTGS): the window
    /// shows frame N-1 (or newer) while the GS thread finishes frame N.
    pending_display: Option<u64>,
    /// The GS's wgpu device (GPU backend).
    gpu_ctx: Option<&'static ssx3_ps2::gs::gpu::GpuContext>,
}

/// libpad button bit for a controller button.
fn gamepad_bit(b: gilrs::Button) -> Option<u16> {
    use gilrs::Button::*;
    Some(match b {
        Select => 1 << 0,
        LeftThumb => 1 << 1,
        RightThumb => 1 << 2,
        Start => 1 << 3,
        DPadUp => 1 << 4,
        DPadRight => 1 << 5,
        DPadDown => 1 << 6,
        DPadLeft => 1 << 7,
        LeftTrigger2 => 1 << 8,
        RightTrigger2 => 1 << 9,
        LeftTrigger => 1 << 10,
        RightTrigger => 1 << 11,
        North => 1 << 12,
        East => 1 << 13,
        South => 1 << 14,
        West => 1 << 15,
        _ => return None,
    })
}

impl App {
    /// Merge keyboard and controller state into pad 1.
    fn update_pad(&mut self) {
        let mut buttons = self.keys;
        let mut sticks = [0x80u8; 4];
        if let Some(g) = self.gilrs.as_mut() {
            while g.next_event().is_some() {}
            if let Some((_, pad)) = g.gamepads().next() {
                for (b, bit) in [
                    gilrs::Button::Select, gilrs::Button::LeftThumb, gilrs::Button::RightThumb,
                    gilrs::Button::Start, gilrs::Button::DPadUp, gilrs::Button::DPadRight,
                    gilrs::Button::DPadDown, gilrs::Button::DPadLeft, gilrs::Button::LeftTrigger2,
                    gilrs::Button::RightTrigger2, gilrs::Button::LeftTrigger, gilrs::Button::RightTrigger,
                    gilrs::Button::North, gilrs::Button::East, gilrs::Button::South, gilrs::Button::West,
                ]
                .into_iter()
                .filter_map(|b| gamepad_bit(b).map(|bit| (b, bit)))
                {
                    if pad.is_pressed(b) {
                        buttons |= bit;
                    }
                }
                // PS2 sticks: 0 = left/up, 0xFF = right/down; gilrs Y is up-positive.
                let axis = |a: gilrs::Axis, flip: bool| {
                    let v = pad.value(a);
                    let v = if flip { -v } else { v };
                    ((v.clamp(-1.0, 1.0) * 127.5) + 127.5).round() as u8
                };
                sticks = [
                    axis(gilrs::Axis::RightStickX, false),
                    axis(gilrs::Axis::RightStickY, true),
                    axis(gilrs::Axis::LeftStickX, false),
                    axis(gilrs::Axis::LeftStickY, true),
                ];
            }
        }
        self.cpu.sif.pad_buttons[0] = buttons;
        self.cpu.sif.pad_sticks[0] = sticks;
    }
}

fn pad_bit(k: KeyCode) -> Option<u16> {
    // libpad button bits (active-low in the wire format; we store active-high).
    Some(match k {
        KeyCode::ShiftRight => 1 << 0,  // Select
        KeyCode::Enter => 1 << 3,       // Start
        KeyCode::ArrowUp => 1 << 4,
        KeyCode::ArrowRight => 1 << 5,
        KeyCode::ArrowDown => 1 << 6,
        KeyCode::ArrowLeft => 1 << 7,
        KeyCode::Digit1 => 1 << 8,      // L2
        KeyCode::Digit2 => 1 << 9,      // R2
        KeyCode::KeyQ => 1 << 10,       // L1
        KeyCode::KeyW => 1 << 11,       // R1
        KeyCode::KeyA => 1 << 12,       // Triangle
        KeyCode::KeyS => 1 << 13,       // Circle
        KeyCode::KeyX => 1 << 14,       // Cross
        KeyCode::KeyZ => 1 << 15,       // Square
        _ => return None,
    })
}

impl ApplicationHandler for App {
    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
        if self.window.is_some() {
            return;
        }
        let attrs = Window::default_attributes()
            .with_title("SSX 3 (USA) — native recompilation")
            .with_inner_size(winit::dpi::LogicalSize::new(960.0, 672.0));
        let window = Arc::new(event_loop.create_window(attrs).expect("window"));
        let gs = self.cpu.bus.hw.gs.core().gpu_context();
        self.gpu_ctx = gs;
        self.presenter = Some(pollster::block_on(Presenter::new(window.clone(), gs)));
        self.window = Some(window);
    }

    fn window_event(&mut self, event_loop: &ActiveEventLoop, _id: WindowId, event: WindowEvent) {
        match event {
            WindowEvent::CloseRequested => event_loop.exit(),
            WindowEvent::Resized(size) => {
                if let Some(p) = self.presenter.as_mut() {
                    p.resize(size.width, size.height);
                }
            }
            WindowEvent::KeyboardInput { event, .. } => {
                if let PhysicalKey::Code(code) = event.physical_key {
                    if code == KeyCode::F12 && event.state == ElementState::Pressed {
                        let (w, h) = self.cpu.bus.hw.gs.core().display(&mut self.frame);
                        let path = format!("/tmp/ssx3-shot-{}.png", self.shots);
                        self.shots += 1;
                        let _ = std::fs::write(&path, png::encode(w, h, &self.frame));
                        eprintln!("screenshot: {path}");
                    }
                    if let Some(bit) = pad_bit(code) {
                        if event.state == ElementState::Pressed {
                            self.keys |= bit;
                        } else {
                            self.keys &= !bit;
                        }
                    }
                }
            }
            WindowEvent::RedrawRequested => {
                self.update_pad();
                let alive = ssx3_ps2::machine::run_frame(&mut self.cpu);
                if self.cpu.sched.frames % 60 == 0 {
                    eprintln!("[{:6.1}s] {}", self.started.elapsed().as_secs_f64(), game::status(&self.cpu));
                    let now = Instant::now();
                    let fps = 60.0 / now.duration_since(self.fps_mark).as_secs_f64().max(1e-6);
                    self.fps_mark = now;
                    if let Some(w) = self.window.as_ref() {
                        w.set_title(&format!("SSX 3 (USA) — native recompilation — {fps:.0} fps"));
                    }
                }
                if !alive {
                    eprintln!("halted: {:?}", self.cpu.kernel.halted);
                    event_loop.exit();
                    return;
                }
                let gs = &mut self.cpu.bus.hw.gs;
                match self.presenter.as_mut() {
                    // GPU GS: the frame stays on the GPU. The display pass
                    // is queued on the GS thread right behind this frame's
                    // drawing; the previous request's frame (or a newer
                    // one) is presented, so the guest never waits for the
                    // GS thread to finish the frame it just produced.
                    Some(p) if p.same_device(self.gpu_ctx) => {
                        let ticket = gs.request_display();
                        let prev = self.pending_display.replace(ticket).unwrap_or(ticket);
                        match gs.take_display(prev) {
                            Some(Some(frame)) => {
                                let _ = p.render_gpu(&frame);
                            }
                            Some(None) => {
                                let (w, h) = gs.core().display(&mut self.frame);
                                let _ = p.render(w, h, &self.frame);
                            }
                            None => {} // nothing new: keep the last image
                        }
                    }
                    Some(p) => {
                        let (w, h) = gs.core().display(&mut self.frame);
                        let _ = p.render(w, h, &self.frame);
                    }
                    None => {}
                }
                if let Some(n) = self.exit_after {
                    if self.cpu.sched.frames >= n {
                        event_loop.exit();
                    }
                }
                // Pace to ~59.94 fields per second.
                let target = Duration::from_micros(16_683);
                let el = self.last.elapsed();
                if el < target {
                    std::thread::sleep(target - el);
                }
                self.last = Instant::now();
            }
            _ => {}
        }
    }

    fn about_to_wait(&mut self, _event_loop: &ActiveEventLoop) {
        if let Some(w) = self.window.as_ref() {
            w.request_redraw();
        }
    }
}

fn main() {
    env_logger::init();
    let cpu = game::boot(false);
    let event_loop = EventLoop::new().expect("event loop");
    event_loop.set_control_flow(ControlFlow::Poll);
    let mut app = App {
        cpu,
        window: None,
        presenter: None,
        frame: Vec::new(),
        last: Instant::now(),
        started: Instant::now(),
        exit_after: std::env::var("SSX3_EXIT_AFTER_FRAMES").ok().and_then(|s| s.parse().ok()),
        shots: 0,
        fps_mark: Instant::now(),
        keys: 0,
        pending_display: None,
        gpu_ctx: None,
        gilrs: gilrs::Gilrs::new().map_err(|e| eprintln!("no game controller support: {e}")).ok(),
    };
    if let Err(e) = event_loop.run_app(&mut app) {
        eprintln!("event loop error: {e}");
        std::process::exit(1);
    }
}
